# 2. List all files and directories in /home/user/ recursively with depth limit 3
def list_files_recursive(root_path, max_depth=3, current_depth=0):
    results = []
    try:
        for item in os.listdir(root_path):
            full_path = os.path.join(root_path, item)
            results.append((full_path, current_depth))

            if current_depth < max_depth - 1 and os.path.isdir(full_path) and not os.path.islink(full_path):
                try:
                    sub_results = list_files_recursive(full_path, max_depth, current_depth + 1)
                    results.extend(sub_results)
                except PermissionError:
                    results.append((f"Permission denied: {full_path}", current_depth + 1))
                except Exception as e:
                    results.append((f"Error accessing {full_path}: {e}", current_depth + 1))
    except PermissionError:
        return [("Permission denied", current_depth)]
    except Exception as e:
        return [(f"Error listing {root_path}: {e}", current_depth)]

    return results

print("Listing files in /home/user/ (depth limit 3):")
try:
    all_files = list_files_recursive('/home/user/', max_depth=3)

    # Group by depth for better visualization
    for depth in range(3):
        print(f"\nDepth {depth}:")
        depth_files = [path for path, d in all_files if d == depth]
        for path in depth_files[:50]:  # Limit output
            print(f"  {path}")

        if len(depth_files) > 50:
            print(f"  ... and {len(depth_files) - 50} more")

except Exception as e:
    print(f"Error: {e}")", "session_id": 1774247959}

