            # Print with indentation
            is_link = os.path.islink(full_path)
            is_dir = os.path.isdir(full_path) and not is_link

            link_info = " [SYMLINK]" if is_link else ""
            print(f"{indent}{item}{link_info}")

            if is_dir and current_depth < max_depth - 1:
